// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    DEP_BANK c;
    LogFile log_;

    function setUp() public {
        c = new DEP_BANK();
        log_ = new LogFile();
        c.SetLogFile(address(log_));
    }

    function testFuzz_property(uint256 am, uint256 dep, address actor, bool makeRevert) public {
        vm.assume(dep <= VALUE_CAP);
        // keep the actor from being the test contract or c itself
        vm.assume(actor != address(this) && actor != address(c));
        // keep the deposit and amount sane but wide
        vm.assume(dep >= am);
        vm.assume(dep <= type(uint128).max);
        vm.assume(am <= type(uint128).max);

        // set a MinSum so the balance condition is met
        uint256 minSum = 0;
        c.SetMinSum(minSum);

        // deploy the failing callee only when makeRevert is true
        if (makeRevert) {
            Reverter rev = new Reverter();
            vm.deal(address(rev), dep);
            vm.prank(address(rev));
            c.Deposit{value: dep}();

            bool ok;
            vm.prank(address(rev));
            try c.Collect(am) { ok = true; } catch { ok = false; }

            // reference: the failed transfer must make Collect revert and leave state unchanged
            // mutant: Collect succeeds, decrements balances[address(rev)] and keeps the ETH
            assertTrue(ok == false && c.balances(address(rev)) == dep && address(c).balance == dep);
        } else {
            // normal successful path also must not diverge in the reference
            address eoa = vm.addr(uint256(keccak256(abi.encode(actor))));
            vm.deal(eoa, dep);
            vm.prank(eoa);
            c.Deposit{value: dep}();

            vm.prank(eoa);
            try c.Collect(am) { } catch { }

            // reference: either success with balance reduced and ETH sent, or revert with balance kept
            // both leave balances and c balance consistent with the amount moved
            assertTrue(c.balances(eoa) == dep - am || c.balances(eoa) == dep);
        }
    }
}

contract Reverter {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}
